<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/session.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../index.php');if(($_SESSION['admin_role']??'admin')==='marshal')redirect('attendance/index.php');
function ams_count($conn,$sql,$params=[]){$r=$params?pg_query_params($conn,$sql,$params):pg_query($conn,$sql);return $r?(int)pg_fetch_result($r,0,0):0;}
$events=ams_count($conn,'SELECT COUNT(*) FROM events');$active=ams_count($conn,"SELECT COUNT(*) FROM events WHERE status IN ('open','ongoing')");$attendees=ams_count($conn,"SELECT COUNT(*) FROM attendees WHERE status='active'");$registrations=ams_count($conn,"SELECT COUNT(*) FROM event_registrations WHERE status='registered'");$present=ams_count($conn,'SELECT COUNT(DISTINCT registration_id) FROM session_attendance WHERE time_in_at IS NOT NULL');$inside=ams_count($conn,'SELECT COUNT(*) FROM session_attendance WHERE time_in_at IS NOT NULL AND time_out_at IS NULL');$rate=$registrations?round($present/$registrations*100,1):0;
$current=pg_query($conn,"SELECT e.*,COUNT(DISTINCT r.id) registrations,COUNT(DISTINCT sa.registration_id) FILTER(WHERE sa.time_in_at IS NOT NULL) present FROM events e LEFT JOIN event_registrations r ON r.event_id=e.id AND r.status='registered' LEFT JOIN event_sessions es ON es.event_id=e.id LEFT JOIN session_attendance sa ON sa.registration_id=r.id AND sa.session_id=es.id WHERE e.status IN ('open','ongoing') GROUP BY e.id ORDER BY e.start_at LIMIT 1");$current=$current&&pg_num_rows($current)?pg_fetch_assoc($current):null;
$recent=pg_query($conn,"SELECT e.*,COUNT(DISTINCT r.id) registrations,COUNT(DISTINCT sa.registration_id) FILTER(WHERE sa.time_in_at IS NOT NULL) present FROM events e LEFT JOIN event_registrations r ON r.event_id=e.id AND r.status='registered' LEFT JOIN event_sessions es ON es.event_id=e.id LEFT JOIN session_attendance sa ON sa.registration_id=r.id AND sa.session_id=es.id GROUP BY e.id ORDER BY e.start_at DESC LIMIT 6");
$activity=pg_query($conn,"SELECT a.full_name,e.title,sa.time_in_at check_in_at,sa.time_out_at check_out_at FROM session_attendance sa JOIN event_registrations r ON r.id=sa.registration_id JOIN attendees a ON a.id=r.attendee_id JOIN event_sessions es ON es.id=sa.session_id JOIN events e ON e.id=es.event_id ORDER BY sa.updated_at DESC LIMIT 10");
admin_page_start('Attendance Overview','dashboard');?>
<div class="welcome-banner"><div><h2><i class="fas fa-calendar-check"></i> Event control center</h2><p><?=date('l, F j, Y')?> · Monitor registration and attendance in real time.</p></div><div class="banner-icon"><i class="fas fa-id-card-clip"></i></div></div>
<?php if($current):?><div class="status-alert ongoing"><i class="fas fa-circle"></i><div><strong><?=h($current['title'])?></strong> · <?=h(date('M j, g:i A',strtotime($current['start_at'])))?> at <?=h($current['venue']?:'Venue TBA')?> · <?=(int)$current['present']?> checked in</div></div><?php else:?><div class="status-alert info"><i class="fas fa-info-circle"></i><div>No event is open right now. Create or open an event to begin registration and check-in.</div></div><?php endif;?>
<div class="stats-grid"><div class="stat-card elections"><div class="stat-icon"><i class="fas fa-calendar-days"></i></div><div><div class="stat-number"><?=$events?></div><div class="stat-label">Events</div><div class="stat-sub"><?=$active?> open or ongoing</div></div></div><div class="stat-card voters"><div class="stat-icon"><i class="fas fa-users"></i></div><div><div class="stat-number"><?=$attendees?></div><div class="stat-label">Attendees</div><div class="stat-sub">Active profiles</div></div></div><div class="stat-card positions"><div class="stat-icon"><i class="fas fa-ticket"></i></div><div><div class="stat-number"><?=$registrations?></div><div class="stat-label">Registrations</div><div class="stat-sub">Across all events</div></div></div><div class="stat-card votes"><div class="stat-icon"><i class="fas fa-user-check"></i></div><div><div class="stat-number"><?=$present?></div><div class="stat-label">Check-ins</div><div class="stat-sub"><?=$inside?> currently inside</div></div></div><div class="stat-card turnout"><div class="stat-icon"><i class="fas fa-percent"></i></div><div><div class="stat-number"><?=$rate?>%</div><div class="stat-label">Attendance Rate</div><div class="stat-sub">Overall conversion</div></div></div></div>
<div class="quick-actions"><h3><i class="fas fa-bolt"></i> Quick Actions</h3><div class="action-buttons"><a href="events/index.php?action=new" class="action-btn primary"><i class="fas fa-plus"></i> Create Event</a><a href="attendees/index.php" class="action-btn secondary"><i class="fas fa-user-plus"></i> Add Attendee</a><a href="attendance/index.php" class="action-btn success"><i class="fas fa-qrcode"></i> Open Check-in Desk</a><a href="reports/index.php" class="action-btn info"><i class="fas fa-file-export"></i> Attendance Reports</a></div></div>
<div class="dashboard-grid"><div class="panel"><div class="panel-header"><h3><i class="fas fa-calendar"></i> Recent Events</h3><a href="events/index.php">View all →</a></div><div class="panel-body"><?php if($recent&&pg_num_rows($recent)):while($e=pg_fetch_assoc($recent)):$pct=(int)$e['registrations']?round((int)$e['present']/(int)$e['registrations']*100):0;?><div class="election-item"><div class="election-info"><h4><?=h($e['title'])?></h4><p><?=h(date('M j, Y · g:i A',strtotime($e['start_at'])))?> · <?=h($e['venue']?:'Venue TBA')?></p><div class="election-meta"><span><i class="fas fa-ticket"></i> <?=(int)$e['registrations']?> registered</span><span><i class="fas fa-user-check"></i> <?=(int)$e['present']?> present</span><span><?=$pct?>%</span></div></div><span class="badge <?=h($e['status'])?>"><?=h(ucfirst($e['status']))?></span></div><?php endwhile;else:?><div class="empty-state"><i class="fas fa-calendar-xmark"></i><p>No events yet.</p></div><?php endif;?></div></div>
<div class="panel"><div class="panel-header"><h3><i class="fas fa-clock-rotate-left"></i> Latest Check-ins</h3></div><div class="panel-body"><?php if($activity&&pg_num_rows($activity)):while($a=pg_fetch_assoc($activity)):?><div class="activity-item"><div class="activity-icon"><i class="fas fa-check"></i></div><div class="activity-info"><strong><?=h($a['full_name'])?></strong><br><small><?=h($a['title'])?></small></div><div class="activity-time"><?=h(date('M j, g:i A',strtotime($a['check_in_at'])))?></div></div><?php endwhile;else:?><div class="empty-state"><i class="fas fa-inbox"></i><p>No attendance activity yet.</p></div><?php endif;?></div></div></div>
<?php admin_page_end();?>
